ALTER TABLE public.stations ADD COLUMN active boolean NOT NULL DEFAULT true;
CREATE OR REPLACE FUNCTION public.validate_duty_log_alcohol() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF coalesce(trim(NEW.alcohol_test_number),'')='' OR NEW.alcohol_test_time IS NULL OR NEW.alcohol_test_result IS NULL THEN RAISE EXCEPTION 'Test d''alcoolémie obligatoire : numéro, heure et résultat'; END IF; IF length(NEW.alcohol_test_number)>100 OR length(NEW.post)>160 OR length(NEW.observations)>2000 THEN RAISE EXCEPTION 'Texte trop long'; END IF; IF NEW.start_time IS NULL OR coalesce(trim(NEW.fonction),'')='' OR NEW.station_depart_id IS NULL OR NEW.station_arrivee_id IS NULL THEN RAISE EXCEPTION 'Fonction, heure de prise et gares obligatoires'; END IF; RETURN NEW; END $$;